bool PSTokenizer::getToken(char *buf, int size, int *length) {
  bool comment, backslash;
  int c;
  int i;

  // skip leading whitespace and comments
  comment = false;
  while (1) {
    if ((c = getChar()) == EOF) {
      buf[0] = '\0';
      *length = 0;
      return false;
    }
    if (comment) {
      if (c == '\x0a' || c == '\x0d') {
        comment = false;
      }
    } else if (c == '%') {
      comment = true;
    } else if (specialChars[static_cast<unsigned char>(c)] != 1) {
      break;
    }
  }

  // Reserve room for terminating '\0'
  size--;

  // read a token
  i = 0;
  buf[i++] = c;
  if (c == '(') {
    backslash = false;
    while ((c = lookChar()) != EOF) {
      consumeChar();
      if (i < size) {
        buf[i++] = c;
      }
      if (c == '\\') {
        backslash = true;
      } else if (!backslash && c == ')') {
        break;
      } else {
        backslash = false;
      }
    }
  } else if (c == '<') {
    while ((c = lookChar()) != EOF) {
      consumeChar();
      if (i < size && specialChars[static_cast<unsigned char>(c)] != 1) {
        buf[i++] = c;
      }
      if (c == '>') {
        break;
      }
    }
  } else if (c != '[' && c != ']') {
    while ((c = lookChar()) != EOF && !specialChars[static_cast<unsigned char>(c)]) {
      consumeChar();
      if (i < size) {
        buf[i++] = c;
      }
    }
  }
  // Zero terminate token string
  buf[i] = '\0';
  // Return length of token
  *length = i;

  return true;
}

int PSTokenizer::lookChar() {
  if (charBuf < 0) {
    charBuf = (*getCharFunc)(data);
  }
  return charBuf;
}

void PSTokenizer::consumeChar() {
  charBuf = -1;
}

int PSTokenizer::getChar() {
  int c = charBuf;

  if (c < 0) {
    c = (*getCharFunc)(data);
  } else {
    charBuf = -1;
  }
  return c;
